def rect_out(g):
    g=[list(r) for r in g]; H=len(g); W=len(g[0])
    bg=g[0][0]
    cs=[(r,c) for r in range(H) for c in range(W) if g[r][c]!=bg]
    rs=[r for r,c in cs]; cc=[c for r,c in cs]
    r0,r1,c0,c1=min(rs),max(rs),min(cc),max(cc)
    out=[row[:] for row in g]
    for c in range(c0,c1+1):
        for r in (r0,r1):
            if out[r][c]==bg: out[r][c]=2
    for r in range(r0,r1+1):
        for c in (c0,c1):
            if out[r][c]==bg: out[r][c]=2
    return out
