                for cc in range(a+1,b): out[r][cc]=2
    for c in range(W):
        rs=sorted(r for r in range(H) if g[r][c]!=bg)
        for a,b in zip(rs,rs[1:]):
            if b-a-1<=maxg:
                for rr in range(a+1,b): out[rr][c]=2
    return out
