def f(g):
    g=[list(r) for r in g]; H=len(g); W=len(g[0])
    bg=g[0][0]; out=[row[:] for row in g]
    runs=[]  # (r,c,start,len,color) and vertical analogs
    for r in range(H):
        c=0
        while c<W:
            if g[r][c]!=bg:
                st=c
                while c<W and g[r][c]==g[r][st]: c+=1
                runs.append(('h',r,st,c-st-1,g[r][st]))
            else: c+=1
    for c in range(W):
        r=0
        while r<H:
            if g[r][c]!=bg:
                st=r
                while r<H and g[r][c]==g[st][c]: r+=1
                runs.append(('v',c,st,r-st-1,g[r-1][c]))
            else: r+=1
    def run_len(pos, orientation='h'):
        # find the run containing pos
        for o,(a,b,s,l,col) in runs:
            if orientation==('h' if o=='h' else 'v') and (o=='h' and b==pos or o=='v' and s==pos): return l+1
        return 1
    for r in range(H):
        pts=[c for c in range(W) if g[r][c]!=bg]
        for i in range(len(pts)-1):
            lo,hi=pts[i],pts[i+1]
            if hi-lo-1<=0: continue
            llen=run_len(lo,'h'); rlen=run_len(hi,'h')
            v_lo=run_len(lo,'v'); v_hi=run_len(hi,'v')
            if llen>=2 or rlen>=2 or v_lo>=2 or v_hi>=2:
                for x in range(lo+1,hi): out[r][x]=2
    for c in range(W):
        pts=[r for r in range(H) if g[r][c]!=bg]
        for i in range(len(pts)-1):
            lo,hi=pts[i],pts[i+1]
            if hi-lo-1<=0: continue
            llen=run_len(lo,'v'); rlen=run_len(hi,'v')
            h_lo=run_len(lo,'h'); h_hi=run_len(hi,'h')
            if llen>=2 or rlen>=2 or h_lo>=2 or h_hi>=2:
                for y in range(lo+1,hi): out[y][c]=2
    return out
