def f(g):
    g=[list(r) for r in g]; H=len(g); W=len(g[0])
    bg=g[0][0]; out=[row[:] for row in g]
    def get_run(pos, axis):  # pos = (r,c), axis 'h' or 'v', returns length of run through pos
        cnt=1
        if axis=='h':
            c=pos[1]
            while True:
                left=(pos[0],c-1); right=(pos[0],c+1)
                if g[left[0]][left[1]]==g[pos[0]][pos[1]] and g[right[0]][right[1]]==g[pos[0]][pos[1]] and not (left[1]<0 or right[1]>=W):
                    c-=1; c+=2; break
                elif g[left[0]][left[1]]==g[pos[0]][pos[1]]:
                    cnt+=1; c-=1
                else: return cnt
                c+=1
        else:
            r=pos[0]
            while True:
                up=(r-1,pos[1]); down=(r+1,pos[1])
                if g[up[0]][up[1]]==g[pos[0]][pos[1]] and g[down[0]][down[1]]==g[pos[0]][pos[1]] and not (up[0]<0 or down[0]>=H):
                    r-=1; r+=2; break
                elif g[up[0]][up[1]]==g[pos[0]][pos[1]]:
                    cnt+=1; r-=1
                else: return cnt
                r+=1
    for r in range(H):
        pts=[c for c in range(W) if g[r][c]!=bg]
        for i in range(len(pts)-1):
            lo,hi=pts[i],pts[i+1]
            if hi-lo-1<=0: continue
            llen=get_run((r,lo),'h'); rlen=get_run((r,hi),'h')
            if llen>=2 or rlen>=2:
                for x in range(lo+1,hi): out[r][x]=2
    for c in range(W):
        pts=[r for r in range(H) if g[r][c]!=bg]
        for i in range(len(pts)-1):
            lo,hi=pts[i],pts[i+1]
            if hi-lo-1<=0: continue
            v_lo=get_run((lo,c),'v'); v_hi=get_run((hi,c),'v')
            if v_lo>=2 or v_hi>=2:
                for y in range(lo+1,hi): out[y][c]=2
    return out
